// Edit only these values for a new episode. Do not paste tokens here.
const config = {
  topic: 'Bakit may amoy ang ulan?',
  angle: 'Explain petrichor in accessible Tagalog with a curious and accurate hook.',
  style: '3d',
  workerBaseUrl: 'https://REPLACE_WITH_YOUR_WORKER.workers.dev'
};
if (typeof config.topic !== 'string' || config.topic.trim().length < 5 || config.topic.length > 120) {
  throw new Error('Topic must be 5–120 characters');
}
if (typeof config.angle !== 'string' || config.angle.length > 180) {
  throw new Error('Angle must be at most 180 characters');
}
if (config.style !== '3d') throw new Error('KURI baseline requires the 3d style');
if (!/^https:\/\/[a-z0-9.-]+$/i.test(config.workerBaseUrl)
 || config.workerBaseUrl.includes('REPLACE_WITH_')) {
  throw new Error('Configure a valid HTTPS Cloudflare Worker URL in Episode Settings');
}
return [{json:config}];

const generated = $input.first().json;
const style = $('Episode Settings').first().json.style;
if (!generated || typeof generated !== 'object'
 || typeof generated.title !== 'string' || generated.title.length < 12
 || typeof generated.hook !== 'string' || generated.hook.length < 8
 || typeof generated.script !== 'string' || generated.script.length < 250) {
  throw new Error('Cloudflare Worker returned an invalid content pack');
}
return [{json:{title:generated.title,hook:generated.hook,script:generated.script,style}}];

const storyboard = $input.first().json;
const content = $('Generate AI Content').first().json;
const cfg = $('Episode Settings').first().json;
if (!Array.isArray(storyboard.scenes) || storyboard.scenes.length !== 7
 || storyboard.style !== '3d') {
  throw new Error('Expected exactly seven 3D storyboard scenes');
}
const host = 'KURI: adult Filipino male science host, about 25 years old, medium-tan skin, masculine jawline, short textured black hair, expressive dark brown eyes, fit adult build, golden-yellow hoodie with a small teal question-mark on chest, navy joggers and white sneakers with teal accents.';
const unique = new Set();
const scenes = storyboard.scenes.map((scene, i) => {
  if (typeof scene.prompt !== 'string' || scene.prompt.length < 125 ||
      typeof scene.voiceoverBeat !== 'string' || scene.voiceoverBeat.length < 10) {
    throw new Error('Incomplete storyboard scene ' + (i + 1));
  }
  const key = scene.prompt.trim().toLowerCase();
  if (unique.has(key)) throw new Error('Duplicate scene prompt');
  unique.add(key);
  return {
    sceneNumber: i + 1,
    clipDurationSeconds: 8,
    sceneTitle: scene.title,
    voiceoverBeat: scene.voiceoverBeat,
    animationPrompt: 'Premium cinematic 3D CGI. ' + host +
      ' KURI is the recurring presenter; maintain consistent facial identity and wardrobe throughout. ' +
      scene.prompt + ' Silent visual only; no on-screen text, dialogue, music or narration.',
  };
});
return [{json:{
  channel:'Bakit Nga Ba?',host:'KURI',language:'Tagalog',
  topic:cfg.topic,style:'3d',title:content.title,hook:content.hook,
  fullVoiceoverScript:content.script,caption:content.caption,
  hashtags:content.hashtags,aspectRatio:'9:16',scenes,
  audioDirection:'ElevenLabs: deep, warm masculine Filipino voice, Metro Manila Tagalog accent.',
  generatedVideo:false,youtubeAutoUpload:false,editorialReviewRequired:true,
  notes:'Review factual claims, scene continuity, audio timing, licensing and AI disclosure before rendering or publishing.'
}}];
